import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';import {join} from 'node:path';import {pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';
import * as original from './index.mjs';
const dir=process.argv[2],provenance=JSON.parse(readFileSync(new URL('./provenance.json',import.meta.url),'utf8'));
for(const [file,sha]of Object.entries(provenance.hashes))assert.equal(createHash('sha256').update(readFileSync(new URL(file,import.meta.url))).digest('hex'),sha);
for(const info of Object.values(provenance.modules)){let text=readFileSync(new URL(info.original,import.meta.url),'utf8').replace("'@deepseek-ai/cosmokit'","'../cosmokit-package/index.js'");for(const dep of ['context','events','fiber','registry','utils','logger','reflect','service'])text=text.replaceAll(`"./${dep}.js"`,`"./${dep}.mjs"`).replaceAll(`'./${dep}.js'`,`'./${dep}.mjs'`);assert.equal(text,readFileSync(new URL(info.oracle,import.meta.url),'utf8'));}
const roots=[...readFileSync(new URL('./original-index.mjs',import.meta.url),'utf8').matchAll(/export \* from "\.\/(\w+)\.js";/g)].map(m=>'cordis.'+m[1]);
assert.deepEqual(roots,['cordis.context','cordis.events','cordis.fiber','cordis.logger','cordis.registry','cordis.service','cordis.utils']);assert.equal(Object.hasOwn(original,'default'),false);assert.equal(Object.keys(original).length,26);
async function run(m){const out=[],group=async(name,fn)=>out.push([name,await fn()]);const context=()=>{const c=new m.Context();c.logger.error=()=>{};return c;},s=m.symbols;
 await group('native Service class and original public barrel',()=>{assert.deepEqual(Object.keys(m).sort(),Object.keys(original).sort());assert.equal(m.Service.name,'Service');assert.equal(m.Service.length,2);assert.equal(Object.hasOwn(m,'default'),false);assert.deepEqual(Object.getOwnPropertyNames(m.Service),Object.getOwnPropertyNames(original.Service));for(const key of ['init','check','config','invoke','extend','tracker','resolveConfig'])assert.equal(m.Service[key],s[key]);return Object.getOwnPropertySymbols(m.Service.prototype).map(k=>Symbol.keyFor(k)||k.description);});
 await group('ordinary service immediate registration and owner cleanup',async()=>{const c=context();class Plain extends m.Service{static provide='api';value=7;read(){return this.value;}}const v=new Plain(c);assert.equal(v.name,'api');assert.equal(v.ctx,c);assert.equal(c.api.read(),7);assert.equal(c.api instanceof Plain,true);assert.equal(v instanceof m.Service,true);assert.equal(Object.getOwnPropertyDescriptor(v,s.tracker).enumerable,false);assert.deepEqual(v[s.tracker],{associate:'api',property:'ctx'});await c.fiber.dispose();assert.equal(c.reflect.get('api',false),undefined);return v.read();});
 await group('explicit nullish default and empty name',async()=>{const c=context();class Named extends m.Service{static provide='fallback';}const a=new Named(c,null),b=new Named(c,'');assert.equal(a.name,'fallback');assert.equal(b.name,'');assert.equal(c.reflect.get('',false).name,'');await c.fiber.dispose();return [a.name,b.name];});
 await group('service duplicate preserves first registration',async()=>{const c=context(),a=new m.Service(c,'api');assert.throws(()=>new m.Service(c,'api'),e=>e.message==='service "api" has been registered at <root>');assert.equal(c.api.name,a.name);await c.fiber.dispose();return true;});
 await group('callable service native function and invocation receiver',async()=>{const c=context();class Callable extends m.Service{static provide='calc';[m.Service.invoke](...values){assert.equal(this.ctx,c);assert.equal(this.name,'calc');return values.reduce((a,b)=>a+b,0);}method(){return this.name;}}const v=new Callable(c);assert.equal(typeof v,'function');assert.equal(v.name,'calc');assert.equal(v instanceof Callable,true);assert.equal(v instanceof m.Service,true);assert.equal(v instanceof Function,true);assert.equal(v(1,2,3),6);assert.equal(c.calc(2,4),6);assert.equal(v.method(),'calc');assert.equal(typeof v.call,'function');await c.fiber.dispose();return [v.length,Object.getOwnPropertyDescriptor(v,'name').enumerable];});
 await group('plain extend retains prototype and overlay properties',async()=>{const c=context();class Plain extends m.Service{value=1;read(){return this.value;}}const v=new Plain(c,'api'),e=v[s.extend]({value:4,extra:2});assert.equal(Object.getPrototypeOf(e),v);assert.equal(e instanceof Plain,true);assert.equal(e.name,'api');assert.equal(e.read(),4);assert.equal(v.read(),1);assert.equal(e[s.tracker],v[s.tracker]);await c.fiber.dispose();return e.extra;});
 await group('callable extend retains service invocation and metadata',async()=>{const c=context();class Callable extends m.Service{[s.invoke](x){return x+(this.offset||0);}}const v=new Callable(c,'calc'),e=v[s.extend]({offset:5});assert.equal(typeof e,'function');assert.equal(Object.getPrototypeOf(e),v);assert.equal(e instanceof Callable,true);assert.equal(e.name,'calc');assert.equal(e(2),7);assert.equal(v(2),2);assert.equal(e[s.tracker],v[s.tracker]);await c.fiber.dispose();return e.length;});
 await group('service filter exact isolation symbol',async()=>{const c=context(),v=new m.Service(c,'api'),child=c.extend({meta:1}),isolated=c.isolate('api',Symbol('other'));assert.equal(v[s.filter](c),true);assert.equal(v[s.filter](child),true);assert.equal(v[s.filter](isolated),false);await c.fiber.dispose();return true;});
 await group('intercept precedence and native shallow merge',async()=>{const c=context(),v=new m.Service(c,'api'),child=c.intercept('api',{a:1,x:'root'}).intercept('api',{b:2,x:'child'});const traced=child.api;assert.equal(traced.ctx,child);const result=traced[s.resolveConfig]({base:1,x:'base'},{head:3,x:'head'});assert.deepEqual(result,{base:1,x:'head',a:1,b:2,head:3});assert.deepEqual(v[s.resolveConfig](),{});await c.fiber.dispose();return result;});
 await group('Config.merge actual receiver and ordered arguments',async()=>{const c=context(),v=new m.Service(c,'api'),calls=[];v.Config={merge(...args){assert.equal(this,v.Config);calls.push(args.map(a=>a.id));return {count:args.length};}};const child=c.intercept('api',{id:'root'}).intercept('api',{id:'child'});const result=child.api[s.resolveConfig]({id:'base'},{id:'head'});assert.deepEqual(calls,[['base','root','child','head']]);assert.deepEqual(result,{count:4});await c.fiber.dispose();return calls;});
 await group('Config optional fallback and falsy base head',async()=>{const c=context(),v=new m.Service(c,'api');v.Config=null;assert.deepEqual(v[s.resolveConfig](false,0),{});v.Config={merge:null};assert.deepEqual(v[s.resolveConfig]({a:1},null),{a:1});v.Config={merge:1};assert.throws(()=>v[s.resolveConfig](),TypeError);await c.fiber.dispose();return true;});
 await group('callable tracked caller context and intercept',async()=>{const c=context();class Callable extends m.Service{[s.invoke](){return [this.ctx.tag,this[s.resolveConfig]()];}}new Callable(c,'api');const child=c.extend({tag:'child'}).intercept('api',{a:1});assert.deepEqual(child.api(),['child',{a:1}]);assert.deepEqual(c.api(),[undefined,{}]);await c.fiber.dispose();return true;});
 await group('actual class plugin provides service until Fiber disposal',async()=>{const c=context(),log=[];class Plugin extends m.Service{static provide='api';[s.init](){log.push('init');return ()=>log.push('cleanup');}read(){return 9;}}const f=await c.plugin(Plugin);assert.equal(f.state,2);assert.equal(c.api.read(),9);assert.equal(c.api instanceof Plugin,true);await f.dispose();assert.equal(c.reflect.get('api',false),undefined);assert.equal(c.registry.size,0);await c.fiber.dispose();return log;});
 await group('actual dependency starts and stops with service plugin',async()=>{const c=context(),log=[],Dependent=ctx=>{log.push(['ready',ctx.api.read()]);return ()=>log.push('dependent-cleanup');};Dependent.inject=['api'];const f=await c.plugin(Dependent);assert.equal(f.state,0);class Provider extends m.Service{static provide='api';read(){return 8;}}const provider=await c.plugin(Provider);await f.await();assert.equal(f.state,2);await provider.dispose();await f.await();assert.equal(f.state,0);await f.dispose();await c.fiber.dispose();return log;});
 await group('service availability check preserves native service receiver',async()=>{const c=context(),log=[];class Checked extends m.Service{static provide='api';[s.check](ctx){assert.equal(this instanceof Checked,true);assert.equal(this.name,'api');assert.equal(ctx,undefined);log.push([this.name,ctx===c]);return false;}}const provider=await c.plugin(Checked);const Dependent=()=>{log.push('unexpected');};Dependent.inject=['api'];const f=await c.plugin(Dependent);assert.equal(f.state,0);await f.dispose();await provider.dispose();await c.fiber.dispose();return log;});
 await group('Symbol.hasInstance follows original constructor/prototype chain',async()=>{const c=context();class Base extends m.Service{}class Child extends Base{}const v=new Child(c,'api');assert.equal(v instanceof Child,true);assert.equal(v instanceof Base,true);assert.equal(v instanceof m.Service,true);for(const value of [null,undefined,false,0,'',{},()=>{}])assert.equal(m.Service[Symbol.hasInstance](value),false);const proxy=new Proxy(Child,{});const fake={constructor:proxy};assert.equal(m.Service[Symbol.hasInstance](fake),true);assert.equal(Base[Symbol.hasInstance](fake),true);assert.equal(Child[Symbol.hasInstance](fake),true);await c.fiber.dispose();return true;});
 await group('Symbol.hasInstance preserves proxy access and exact thrown reason',()=>{const log=[],err={kind:'getter'},constructor=new Proxy(function C(){},{get(t,k,r){log.push(String(k));if(k==='prototype')throw err;return Reflect.get(t,k,r);}});assert.throws(()=>m.Service[Symbol.hasInstance]({constructor}),e=>e===err);return log;});
 await group('failed service initialization rolls back registered service',async()=>{const c=context(),err=new Error('service-init');class Broken extends m.Service{static provide='api';[s.init](){throw err;}}const f=c.plugin(Broken);await assert.rejects(Promise.resolve(f),e=>e===err);assert.equal(f.state,3);await f.dispose();assert.equal(c.reflect.get('api',false),undefined);await c.fiber.dispose();return true;});
 return out;
}
let groups=0;
for(const target of ['js','js-browser']){const meta=JSON.parse(readFileSync(join(dir,target+'.json'),'utf8')),folder=join(dir,target),entry=readFileSync(join(folder,meta.entry),'utf8');assert.equal(Object.keys(meta['module-files']).length,15);const rootFiles=[...entry.matchAll(/export \* from "\.\/(module-\d+\.mjs)";/g)].map(m=>m[1]);assert.deepEqual(rootFiles,roots.map(name=>meta['module-files'][name]));const m=await import(pathToFileURL(join(folder,meta.entry)));for(const name of roots){const leaf=await import(pathToFileURL(join(folder,meta['module-files'][name])));for(const key of Object.keys(leaf))assert.equal(m[key],leaf[key]);}const actual=await run(m),expected=await run(original);assert.deepEqual(actual,expected);groups+=actual.length;console.log(`Whole Cordis Service/index actual ${target} native ESM CLI: ${actual.length} paired groups; complete original runtime, native barrel identities and real core owners.`);}
assert.equal(groups,36);console.log('Whole Cordis Service/index:36 paired Node runtime groups; public/new-profile types and full Harness/browser/native/Q9 remain pending.');
